import { launch } from '/www/server/nodejs/v22.22.2/lib/node_modules/cloakbrowser/dist/index.js';

const browser = await launch({ headless: true });
const page = await browser.newPage();
await page.goto('https://mp.weixin.qq.com/s/Z0b2KIDUmN5y7MQYPCF6XA');
await page.waitForLoadState('networkidle');
const content = await page.content();
console.log(content);
await browser.close();
EOF
node cloaktask.mjs 2>&1 | head -300

cd /tmp && cat > cloaktask2.mjs << 'EOF'
import { launch } from '/www/server/nodejs/v22.22.2/lib/node_modules/cloakbrowser/dist/index.js';

const browser = await launch({ headless: true });
const page = await browser.newPage();
await page.goto('https://mp.weixin.qq.com/s/Z0b2KIDUmN5y7MQYPCF6XA');
await page.waitForLoadState('networkidle');

// Extract readable text
const text = await page.evaluate(() => {
  // Remove script and style elements
  const clone = document.body.cloneNode(true);
  const scripts = clone.querySelectorAll('script, style, noscript');
  scripts.forEach(el => el.remove());

  // Get article content
  const article = clone.querySelector('#js_content') || clone.querySelector('.article-content') || clone.querySelector('section');
  if (article) return article.innerText;

  return clone.body.innerText;
});

console.log(text.substring(0, 5000));
await browser.close();
EOF
node cloaktask2.mjs 2>&1

